"""Editorial identity and the intentionally simple email submission route."""
from html import escape as e
from urllib.parse import quote

EMAIL = 'nalar.hakim77@gmail.com'
FORMATS = {
    'esai': ('Esai', 'Mengembangkan pendapat dan membahas pemikiran tentang hukum.'),
    'telaah': ('Telaah Fenomena', 'Membahas peristiwa yang sedang terjadi beserta persoalan hukumnya.'),
    'bedah': ('Bedah Putusan atau Norma', 'Memeriksa alasan dalam putusan atau aturan serta akibatnya.'),
}

MAILTO = 'mailto:' + EMAIL + '?subject=' + quote('Naskah Nalar Hakim — Judul tulisan')


def invitation(prefix=''):
    return f'''<section class="editorial-invitation" aria-labelledby="undangan-naskah"><div><span class="eyebrow">TERBUKA UNTUK KONTRIBUTOR</span><h2 id="undangan-naskah">Punya tulisan<br>tentang hukum?</h2><p>Kirim naskah Word dengan nama samaran. Tidak ada biaya atau akun yang perlu dibuat di situs ini. Redaksi membaca naskah dan mengabari Anda lewat email.</p></div><a class="editorial-button" href="{prefix}kirim-naskah.html">Kirim naskah <span aria-hidden="true">↗</span></a></section>'''


def form_links(prefix=''):
    rows = ''.join(f'<a class="format-card" href="{prefix}bentuk/{slug}/"><span class="eyebrow">0{index}</span><h3>{e(label)}</h3><p>{e(description)}</p><span class="format-arrow" aria-hidden="true">↗</span></a>' for index,(slug,(label,description)) in enumerate(FORMATS.items(),1))
    return '<section class="formats-section"><div class="section-heading"><h2>Tiga bentuk tulisan</h2><span class="eyebrow">BENTUK TULISAN</span></div><div class="formats-grid">'+rows+'</div></section>'


def about_page():
    return '''<main id="main-content" class="container"><article class="article-layout"><header class="article-header"><span class="eyebrow">ARAH NALAR HAKIM</span><h1>Nama samaran.<br>Tulisan untuk semua.</h1><p class="article-deck">Penulis tidak harus membuka identitasnya agar gagasannya bisa dibaca. Mengirim naskah dan membaca artikel di Nalar Hakim tidak dipungut biaya.</p></header><div class="article-content"><p>Nalar Hakim dibangun untuk menjawab dua persoalan: keamanan identitas penulis dan sulitnya membawa tulisan kepada pembaca tanpa biaya atau urusan administrasi yang panjang. Penulis dapat memakai nama samaran. Pembaca dapat membuka seluruh tulisan tanpa akun dan tanpa langganan.</p><h2>Hukum bisa dipertanyakan</h2><p>Kami menerbitkan tulisan tentang aturan, putusan, peristiwa, dan pemikiran hukum. Sebuah tulisan bisa dimulai dari hal sederhana: alasan putusan yang belum meyakinkan, aturan yang membebani orang tertentu, atau pengalaman yang berbeda dari janji hukum.</p><p>Penulis perlu menjelaskan apa yang dipersoalkan, mengapa hal itu penting, dan apa dasar pendapatnya. Teori dapat membantu pembahasan, tetapi menyebut seorang pemikir saja belum cukup. Pembaca harus bisa mengikuti hubungan antara sumber, alasan, dan kesimpulannya.</p><h2>Mengirim naskah tidak perlu rumit</h2><p>Siapa pun dapat mengirim naskah Word lewat email. Tidak ada biaya pengiriman atau penerbitan, syarat gelar, CV, maupun formulir pendaftaran di situs. Redaksi tetap membaca naskah sebelum terbit dan membicarakan revisi lewat email yang sama.</p><p><strong>Esai, Telaah Fenomena, serta Bedah Putusan atau Norma</strong> adalah tiga bentuk tulisan yang kami terima. Pilih yang paling sesuai dengan cara Anda membahas persoalan.</p><h2>Penulis memakai nama samaran</h2><p>Anonimitas membantu penulis memisahkan pendapatnya dari identitas pribadi. Anda dapat memilih nama samaran atau menerbitkan tulisan sebagai Anonim. Nama asli, gelar, dan tempat bekerja tidak diminta sebagai syarat kiriman. Lazarus adalah nama samaran pengelola dan penyunting; tulisan kontributor tetap memakai nama samaran masing-masing.</p><p>Identitas pribadi yang diketahui melalui korespondensi tidak dicantumkan dalam publikasi. Namun, email biasa tidak menjamin anonimitas teknis. Untuk memisahkan identitas pribadi, Anda bisa memakai alamat email khusus serta memeriksa nama pembuat dan komentar dalam berkas sebelum mengirim.</p><h2>Sesudah naskah masuk</h2><p>Lazarus membaca isi dan sumber naskah, lalu mengabari penulis apakah tulisan diterima, perlu diperbaiki, atau belum bisa diterbitkan. Perubahan yang memengaruhi isi dibicarakan dengan penulis sebelum publikasi. Mengirim naskah tidak otomatis menjamin penerbitan.</p><p>Setiap artikel menyertakan rujukan. Jika menemukan kekeliruan fakta atau sumber, pembaca dapat menghubungi redaksi. Koreksi yang mengubah isi tulisan dicatat pada artikelnya.</p><h2>Terbuka untuk dibaca</h2><p>Tulisan yang terbit tersedia untuk siapa saja secara gratis. Tidak ada akun, langganan, atau pembayaran untuk membuka artikel. Donasi bersifat sukarela dan tidak memengaruhi keputusan redaksi.</p><div class="inline-actions"><a class="read-link" href="kirim-naskah.html">Panduan kiriman</a><a class="read-link" href="kebijakan-redaksi.html">Kebijakan Lazarus</a></div></div></article>'''+invitation()+'</main>'


def submission_page():
    return f'''<main id="main-content" class="container submission-main"><header class="archive-header"><span class="eyebrow">KIRIM NASKAH / TANPA AKUN</span><h1>Kirim tulisan Anda.</h1><p class="section-intro">Tanpa biaya dan tanpa akun di situs. Cukup kirim naskah Word dengan nama samaran lewat email; redaksi akan membaca dan mengabari Anda.</p></header><div class="submission-layout"><section aria-labelledby="langkah-kiriman"><h2 id="langkah-kiriman" class="submission-heading">Tiga langkah lewat email.</h2><ol class="submission-steps"><li><span class="step-number" aria-hidden="true">01</span><div><h3>Siapkan naskah Word</h3><p>Lampirkan file <strong>.docx atau .doc</strong> yang berisi judul, nama samaran atau “Anonim”, isi tulisan, dan sumber rujukan. Tidak perlu CV, gelar, atau format jurnal tertentu.</p><p>Jelaskan persoalan yang ingin Anda bahas, pendapat Anda, dan alasan yang mendukungnya. Sertakan sumber agar pembaca dapat memeriksa dasar tulisan.</p></div></li><li><span class="step-number" aria-hidden="true">02</span><div><h3>Kirim ke email redaksi</h3><p>Gunakan subjek <strong>Naskah Nalar Hakim — Judul tulisan</strong>. Sertakan file Word sebagai lampiran dan pernyataan bahwa karya tersebut milik Anda serta diajukan untuk diterbitkan.</p></div></li><li><span class="step-number" aria-hidden="true">03</span><div><h3>Redaksi membaca naskah</h3><p>Lazarus mengabari Anda apakah naskah diterima, perlu direvisi, atau belum dapat diterbitkan. Semua pembicaraan berlangsung lewat email. Pantau kotak masuk dan folder spam.</p></div></li></ol></section><aside class="submission-contact" aria-labelledby="alamat-redaksi"><span class="eyebrow">ALAMAT PENGIRIMAN</span><h2 id="alamat-redaksi">Email redaksi</h2><a class="submission-email" href="mailto:{EMAIL}">{EMAIL}</a><div class="submission-actions"><a class="editorial-button" href="{MAILTO}">Tulis email pengiriman <span aria-hidden="true">↗</span></a><button type="button" class="editorial-button secondary" data-copy-email="{EMAIL}" hidden>Salin alamat email</button></div><p data-email-status role="status" aria-live="polite"></p><p class="submission-hint">Tombol membuka aplikasi email Anda. Lampirkan naskah Word sebelum mengirim. Jika tidak terbuka, salin alamat di atas ke layanan email yang biasa Anda gunakan.</p><div class="privacy-note"><h3>Jaga identitas dalam kiriman</h3><p>Gunakan nama samaran. Jika ingin memisahkan identitas pribadi, pakai alamat email khusus dan periksa nama pembuat serta komentar di berkas Word. Email biasa tidak menjamin anonimitas teknis.</p></div></aside></div><section class="review-section" aria-labelledby="hasil-tinjauan"><div class="section-heading"><h2 id="hasil-tinjauan">Setelah dibaca</h2><a href="kebijakan-redaksi.html">Kebijakan Lazarus ↗</a></div><div class="review-grid"><article><span class="eyebrow">01 / LAYAK</span><h3>Diterbitkan.</h3><p>Naskah diterima setelah isi dan sumbernya diperiksa. Tulisan terbit dengan nama samaran yang Anda pilih, atau sebagai Anonim.</p></article><article><span class="eyebrow">02 / POTENSIAL</span><h3>Disunting.</h3><p>Ada bagian yang perlu diperjelas atau dilengkapi. Redaksi menghubungi Anda lewat email; perubahan isi dibicarakan sebelum terbit.</p></article><article><span class="eyebrow">03 / TIDAK SESUAI</span><h3>Tidak diterbitkan.</h3><p>Naskah belum sesuai dengan pokok bahasan atau pertimbangan redaksi. Keputusannya dikabarkan lewat email.</p></article></div></section></main>'''


def policy_page():
    return f'''<main id="main-content" class="container"><article class="article-layout"><header class="article-header"><span class="eyebrow">KEBIJAKAN REDAKSI / LAZARUS</span><h1>Cara kami<br>menilai naskah.</h1><p class="article-deck">Mengirim dan menerbitkan tulisan tidak dipungut biaya. Setiap naskah tetap dibaca oleh Lazarus sebelum diputuskan untuk terbit.</p></header><div class="article-content"><h2>Arah tulisan</h2><p>Nalar Hakim memuat kritik terhadap peristiwa hukum, putusan, aturan, dan pemikiran. Tulisan perlu menunjukkan persoalan yang dibahas, pendapat penulis, serta alasan yang mendukungnya. Uraian definisi atau rangkuman umum saja belum cukup.</p><h2>Teori dan sumber</h2><p>Teori perlu dipakai untuk menjelaskan persoalan, bukan sekadar disebut. Klaim tentang fakta dan isi dokumen memerlukan sumber yang dapat diperiksa. Utamakan teks aturan, putusan, dokumen resmi, serta karya pemikir yang benar-benar digunakan. Bedakan fakta, penafsiran, dugaan, dan penilaian.</p><p>Penulis bebas memilih format rujukan yang jelas. Redaksi dapat merapikan penyajiannya. Kutipan harus sesuai dengan sumbernya dan menyebutkan penulis atau asalnya; karya hasil penjiplakan atau sumber yang direkayasa tidak diterbitkan.</p><h2>Keputusan Lazarus</h2><p>Redaksi mengabari penulis apakah naskah diterima, perlu direvisi, atau belum bisa diterbitkan. Naskah dapat dikembalikan untuk memperjelas alasan, melengkapi sumber, atau memperbaiki susunannya. Keputusan dan pembicaraan revisi disampaikan lewat email.</p><p>Redaksi dapat merapikan susunan, bahasa, dan rujukan, serta meminta penjelasan atas alasan dalam naskah. Perubahan yang memengaruhi isi dibicarakan dengan penulis sebelum terbit. Pengiriman naskah tidak berarti jaminan terbit.</p><h2>Nama samaran dan korespondensi</h2><p>Karya terbit dengan nama samaran yang dipilih kontributor atau sebagai Anonim. Nama asli, afiliasi, dan gelar tidak diwajibkan. Identitas pribadi yang diketahui dalam korespondensi tidak dimasukkan ke publikasi.</p><p>Pengiriman menggunakan email biasa. Alamat khusus dapat membantu memisahkan identitas pribadi, tetapi tidak menjamin anonimitas teknis. Periksa metadata dan komentar dalam dokumen serta detail cerita yang dapat mengungkap identitas sebelum mengirim.</p><h2>Kebebasan berpendapat</h2><p>Kesimpulan tidak harus sejalan dengan Lazarus. Tulisan dapat mengkritisi lembaga, kebijakan, putusan, norma, dan teori secara mendasar. Kekuatan argumen dan bukti menjadi dasar penilaian; serangan pribadi, pembukaan identitas pihak lain, dan tuduhan tanpa dukungan memadai tidak diterbitkan.</p><p>Penulis perlu memberi tahu redaksi bila memiliki keterlibatan atau kepentingan langsung yang relevan dengan pokok tulisan. Informasi yang diperlukan agar pembaca memahami posisi tulisan dapat disajikan tanpa mencantumkan identitas pribadi.</p><h2>Koreksi tulisan</h2><p>Kirim judul tulisan, bagian yang dipersoalkan, dan sumber pembanding ke <a href="mailto:{EMAIL}">{EMAIL}</a>. Redaksi memeriksa kekeliruan fakta dan mencatat koreksi yang mengubah isi pada artikelnya.</p><p>Lazarus berwenang menarik tulisan bila ditemukan masalah mendasar pada sumber atau keasliannya. Redaksi menjelaskan alasan penarikan tanpa membuka informasi pribadi penulis.</p><h2>Dukungan dan independensi</h2><p>Pengiriman naskah dan akses membaca tidak dipungut biaya. Donasi tidak memberikan hak untuk menentukan tulisan yang terbit atau mengubah kesimpulan penulis.</p><a class="read-link" href="kirim-naskah.html">Kirim karya Anda</a></div></article></main>'''
